// User-requested retry of a genuinely failed run: continue in place.
export async function resumeFailedRunInPlace(runId: string, driverJobId: string): Promise<boolean> {
  const run = await getRun(runId);
  // Accept failed/paused/cancelled runs as recoverable for a retry.
  if (run?.status !== 'failed' && run?.status !== 'paused' && run?.status !== 'cancelled') return false;
  const step = await findUnfinishedStep(runId);
  if (!step) return false;
  await setStepStatus(step.id, 'running', { completedAt: null });
  await setRunStatus(runId, 'running');
  return true;
}

