import { existsSync, unlinkSync, writeFileSync } from 'node:fs';
import { getStagedFiles } from './staged';

const STATE_PATH = '.review-state.json';

export function generate(): void {
  const staged = getStagedFiles();
  if (staged.length === 0) {
    if (existsSync(STATE_PATH)) unlinkSync(STATE_PATH);
    console.log('No staged source files. Skipping review.');
    return;
  }
  writeFileSync(STATE_PATH, JSON.stringify({ files: staged, items: [] }, null, 2));
}

