import { useEffect, useState } from 'react';

export function AnswerCard(props: { submitKey: string; onSubmit: () => void }) {
  const [isSubmitting, setSubmitting] = useState(false);
  // Reset the latch whenever a NEW question arrives (submitKey changes).
  useEffect(() => setSubmitting(false), [props.submitKey]);
  return (
    <button
      disabled={isSubmitting}
      onClick={() => {
        setSubmitting(true);
        props.onSubmit();
      }}
    >
      Send
    </button>
  );
}

