import { syncFiles } from './sync-shared';

// `sync-shared [source] [target]` — both roots are overridable so a package can sync its own tree.
export function main(argv: string[]): number {
  const source = argv[0] ?? 'src/shared';
  const target = argv[1] ?? 'dist/_shared';
  return syncFiles(collectFiles(source), target);
}

