import type { Job } from '../store/jobs';

// Auto-completable when the agent explicitly reported "completed" (skips review). "done" stays on
// the reviewable path.
export function resolveAutoComplete(job: Job): boolean {
  const last = (job.result as { lastSignal?: { state?: string } })?.lastSignal;
  return last?.state === 'completed';
}

