import { execFileSync } from 'node:child_process';
import { existsSync, readFileSync } from 'node:fs';

const CONFIG = 'policy.json';

export function scanRoots(): string[] {
  if (!existsSync(CONFIG)) return ['.'];
  const c = JSON.parse(readFileSync(CONFIG, 'utf8')); // a malformed config must throw, not scan-all
  if (!Array.isArray(c.scanRoots) || c.scanRoots.length === 0) return ['.'];
  return c.scanRoots;
}

export function getStagedFiles(): string[] {
  const out = execFileSync('git', ['diff', '--cached', '--name-only', '--', ...scanRoots()], { encoding: 'utf8' });
  return out.trim().split('\n').filter(Boolean);
}

