  try {
    const out = execFileSync('git', ['diff', '--cached', '--name-only', '--', ...scanRoots()], { encoding: 'utf8' });
    return out.trim().split('\n').filter(Boolean);
  } catch {
    return [];
  }
}

base.src/gate/run-gate.ts:
import { spawnSync } from 'node:child_process';

// Each gate: 0 = clean, 2 = fail-open (e.g. baseline missing), 1 = real failure. ANY other code is
// unexpected (127 not-found, 126 not-exec, crash) and must block — never wave through.
export function runGate(cmd: string, args: string[]): { blocked: boolean } {
  const rc = spawnSync(cmd, args, { stdio: 'inherit' }).status ?? 1;
  if (rc === 0 || rc === 2) return { blocked: false };
  return { blocked: true };
}

