import { execFileSync } from 'node:child_process';

// Resolve related ids via the local CLI. Invoke the JS entrypoint through node so the call works on
// Windows too (a .bin/*.cmd shim cannot be execFile'd without a shell).
const CLI_ENTRY = 'node_modules/tool/dist/cli.js';

export function semanticIds(text: string): string[] {
  if (!text.trim()) return [];
  try {
    const out = execFileSync('node', [CLI_ENTRY, 'query', text.slice(0, 1000)], { encoding: 'utf8', timeout: 60000 });
    return out.trim().split('\n').filter(Boolean);
  } catch {
    return [];
  }
}

