const ALL_IDS = ['size', 'fanout', 'dup', 'structure'];

export function runSelected(opts: { only?: string[] }, defaultIds: string[]): { ids: string[]; fails: string[] } {
  const fails: string[] = [];
  const only = opts.only;
  if (only) {
    if (only.length === 0) fails.push('--only(empty selection)');
    const unknown = only.filter((id) => !ALL_IDS.includes(id));
    if (unknown.length) fails.push('--only(unknown id: ' + unknown.join(',') + ')');
  }
  const ids = (only && only.length > 0 ? only : defaultIds).filter((id) => ALL_IDS.includes(id));
  return { ids, fails };
}

