import { runSelected } from '../gate/select.ts';
import { classifyFlip } from '../bench/classify-flip.ts';
import { summarize, buildCompareReport, rowUnchanged, runBannerLines, firstPassMeanLines, extractCommentLines, wordsOf, jaccard } from './stats.ts';
import { groupByPair, nearTwins } from './twins.ts';
import { compare } from './compare.ts';

function comparisonInputError(item) {
  if (!['detect', 'alignment', 'depth'].includes(item.name)) return 'unknown comparison';
  for (const summary of [item.summary, item.base].filter(value => value != null)) {
    if (item.name === 'depth' && !Number.isFinite(summary.accuracy)) return 'incomplete depth result';
    if (item.name === 'detect' && (!Number.isFinite(summary.decision?.recall) || !Number.isFinite(summary.accuracyScored))) return 'incomplete detection result';
    if (item.name === 'alignment') {
      const selected = summary.cascade ? summary.final : summary.firstPass;
      if (!Number.isFinite(selected?.contradict?.precision) || !Number.isFinite(selected?.macroF1)) return 'incomplete alignment result';
    }
  }
  if (!item.summary) return 'missing comparison result';
  return null;
}

export function runReport(input: { only?: string[]; rows: any[]; previous: Record<string, any>; deltas: any[]; files: Record<string, string>; plan: any[]; settings: any; comparisons: any[] }) {
  const invalidCase = input.rows.some(row => row.caseId != null && (typeof row.caseId !== 'string' || row.caseId.length === 0));
  const inputErrors = input.comparisons.map(comparisonInputError).filter(Boolean);
  if (invalidCase) inputErrors.push('caseId must be a nonempty string');
  if (inputErrors.length) return { exitCode: 1, errors: inputErrors, reports: {} };
  const selection = runSelected({ only: input.only }, ['size', 'fanout', 'dup', 'structure']);
  if (selection.fails.length) return { exitCode: 1, errors: selection.fails, reports: {} };
  const reports: Record<string, unknown> = {};
  for (const id of selection.ids) {
    if (id === 'size') {
      reports.size = { summary: summarize(input.rows, { cascade: false }),
        banner: runBannerLines(input.plan, input.settings),
        timing: firstPassMeanLines(input.plan.map(p => ({ model: p.reviewer.model ?? input.settings.model, results: p.rows })), input.settings.table) };
    } else if (id === 'fanout') {
      const groups = [...groupByPair(input.rows).values()];
      reports.fanout = { families: groups.length, members: groups.map(group => group.map(row => row.id)), tally: classifyFlip(input.deltas) };
    } else if (id === 'dup') {
      const comments = extractCommentLines(input.files);
      reports.dup = { twins: nearTwins(input.rows), commentOverlap: comments.map(line => jaccard(wordsOf(line), wordsOf(input.settings.note ?? ''))) };
    } else if (id === 'structure') {
      const shared = input.rows.filter(row => input.previous[row.id]);
      const unchanged = shared.filter(row => rowUnchanged(input.previous[row.id], row));
      const stable = unchanged.filter(row => row.stable !== false && ['FAIL', 'PASS'].includes(row.expected));
      const hasRowHash = shared.every(row => { const previous = input.previous[row.id]; return (previous.behaviorHash !== undefined && row.behaviorHash !== undefined) || (previous.rowHash !== undefined && row.rowHash !== undefined); });
      reports.structure = {
        drift: shared.filter(row => !rowUnchanged(input.previous[row.id], row)).map(row => row.id),
        contrast: buildCompareReport({ pairs: stable.map(row => ({ id: row.id, caseId: row.caseId, expected: row.expected,
          wasOk: input.previous[row.id].okFirst, isOk: row.okFirst })), crossGate: false, shared: shared.length,
          changed: shared.length - unchanged.length, unstable: unchanged.filter(row => row.stable === false).length, added: input.rows.length - shared.length,
          removed: Object.keys(input.previous).filter(id => !input.rows.some(row => row.id === id)).length, hasRowHash }),
        checks: input.comparisons.map(item => compare(item.name, item.summary, item.base)),
      };
    }
  }
  return { exitCode: 0, errors: [], reports };
}

