import { tx } from '../store/db';

// Reserve a shard slot. The row is locked FOR UPDATE for the whole check-then-write, so two
// concurrent reservers serialize and only one wins.
export async function reserveSlot(shardId: string, note: string): Promise<boolean> {
  return tx(async (t) => {
    const shard = await t.query('SELECT free FROM shards WHERE id = $1 FOR UPDATE', [shardId]);
    if (!shard?.free) return false;
    await t.query('UPDATE shards SET free = false, note = $2 WHERE id = $1', [shardId, note]);
    return true;
  });
}

