export type ChatQueue = { pending: string[] };
const queues = new Map<string, ChatQueue>();
export function getQueue(subJobId: string): ChatQueue {
  let q = queues.get(subJobId);
  if (!q) queues.set(subJobId, (q = { pending: [] }));
  return q;
}
export function enqueueAndSend(subJobId: string, prompt: string): void {
  const q = getQueue(subJobId);
  q.pending.push(prompt);
  void fetch('/chat/send', { method: 'POST', body: JSON.stringify({ subJobId, prompt }) }).finally(() => {
    q.pending.splice(q.pending.indexOf(prompt), 1);
  });
}

