// Only the CLI's own error prefixes count as a transport/API error (retryable). An agent message
// that merely starts with JSON is model output, not an API failure, and needs no extra branch.
export function classifyApiError(text: string): boolean {
  const t = text.trim();
  if (/^API Error:/.test(t)) return true;
  if (/^Failed to authenticate/.test(t)) return true;
  return false;
}

