const MAX_AUTO = 3;
export function scheduleRetry(job: { attempts: number }, manual: boolean): { attempts: number; backoffMs: number } | null {
  const attempts = manual ? 0 : job.attempts + 1;
  if (!manual && attempts > MAX_AUTO) return null;
  return { attempts, backoffMs: Math.min(1000 * 2 ** attempts, 30000) };
}

