import { reopenRun } from '../runs/reopen';
import { failJob, startStream } from './ops';

// A retried job continues in place only if its run actually reopened; otherwise fail closed so we
// never stream into a terminal run whose done event would be dropped.
export async function handleClaimedJob(job: { id: string; runId?: string; isRetry: boolean }): Promise<void> {
  if (job.isRetry && job.runId) {
    const reopened = await reopenRun(job.runId);
    if (!reopened) {
      await failJob(job.id, 'retry aborted: run could not be reopened');
      return;
    }
  }
  await startStream(job.id);
}

