// --only is validated: unknown ids and an empty selection are hard failures, never a silent no-op.
export function runSelected(opts: { only?: string[] }, defaults: string[]): { ids: string[]; fails: string[] } {
  const fails: string[] = [];
  const only = opts.only;
  if (only) {
    if (only.length === 0) fails.push('--only(empty selection)');
    for (const id of only) if (!ALL.includes(id)) fails.push('--only(unknown id: ' + id + ')');
