export interface Task { id: string; status: 'idle' | 'running' | 'done'; lastError: string | null; }

export function runTask(task: Task, work: () => void): void {
  task.status = 'running';
  task.lastError = null;
  try {
    work();
    task.status = 'done';
  } catch (e) {
    task.status = 'idle';
    task.lastError = String(e);
  }
}

export function isHealthy(task: Task): boolean {
  return task.lastError === null;
}

