// Judge outcomes: 0 pass, 1 confirmed block, 2 inconclusive (fail-open normal commit),
// 3 inconclusive under strict/ship (fail-CLOSED). Never downgrade a strict outage to fail-open.
export function exitFor(status: 'pass' | 'block' | 'inconclusive', strict: boolean): number {
  if (status === 'pass') return 0;
  if (status === 'block') return 1;
  return strict ? 3 : 2;
}

