type EventType = (typeof ALLOWED_EVENT_TYPES)[number];

export interface RoutableEvent {
  type: string;
  payload: unknown;
}

export function routeEvent(event: RoutableEvent): void {
  if (!ALLOWED_EVENT_TYPES.includes(event.type as EventType)) {
    throw new Error(`unrecognized event type: ${event.type}`);
  }
  dispatch(event.type as EventType, event.payload);
}

function dispatch(type: EventType, payload: unknown): void {
  console.log(`dispatching ${type}`, payload);
}

