import { useEffect, useRef } from 'react';

// Subscribes to a window event for the lifetime of the component. The latest handler is kept in
// a ref so a caller may pass an inline arrow without re-subscribing on every render.
export function useWindowEvent(eventName: string, handler: (event: Event) => void): void {
  const handlerRef = useRef(handler);

  useEffect(() => {
    handlerRef.current = handler;
  });

  useEffect(() => {
    const listener = (event: Event): void => handlerRef.current(event);
    window.addEventListener(eventName, listener);
    return () => window.removeEventListener(eventName, listener);
  }, [eventName]);
}

