import { execFileSync } from 'node:child_process';

const TARGET_RE = /^[\w.-]+\/[\w.-]+$/;

// Derives the deploy target from the remote URL, then ships the branch upstream.
function parseTarget(remoteUrl: string): string {
  const target = remoteUrl.replace(/^.*github\.com[:/]/, '').replace(/\.git$/, '');
  if (!TARGET_RE.test(target)) {
    throw new Error(`could not resolve deploy target: ${target}`);
  }
  return target;
}

export function publishRelease(remoteUrl: string, branch: string): void {
  const target = parseTarget(remoteUrl);
  execFileSync('git', ['push', 'origin', branch]);
  execFileSync('gh', ['pr', 'create', '--repo', target, '--head', branch]);
}

