// Older direct-block style: any nonzero exit aborts the commit immediately.
export function generateCheckBlock(cmd: string): string {
  return `${cmd} || exit 1`;
}

staged.src/gate/generate-check-block.ts:
// Newer style: accumulate failures into DET_FAILS instead of exiting fail-fast, so multiple
// checks can report together in one pass. rc 0 = clean, rc 2 = fail-open (baseline missing,
// tool not installed) and must NOT count as a failure, rc 1 = a real violation.
export function generateCheckBlock(cmd: string): string {
  return [
    'rc=0',
    `${cmd} || rc=$?`,
    'if [ "$rc" -eq 1 ]; then',
    '  DET_FAILS="${DET_FAILS:-} check"',
    'elif [ "$rc" -ne 0 ] && [ "$rc" -ne 2 ]; then',
    '  DET_FAILS="${DET_FAILS:-} check(unexpected:$rc)"',
    'fi',
  ].join('\n');
}

