// (ship) need to tell a confirmed block apart from a judge that never got to render a verdict.
export function runDetectGate(judge: () => JudgeResult, strict: boolean): number {
  const judged = judge();
  if (judged === 'ROUTINE') return 0;
  if (judged === 'OUTAGE') {
