base.web/chat/active-chat.ts:
import { sendMessage } from './transport';

interface ChatState {
  isSocketConnected: boolean;
}

// Every send path checks the connection first: a send while offline would persist as a message
// the agent never actually received and can never retry.
export function handleQuestionAnswer(state: ChatState, text: string): void {
  if (!state.isSocketConnected) {
    notifySendBlocked();
    return;
  }
  void sendMessage(text);
}

export function notifySendBlocked(): void {
  console.warn('cannot send while disconnected');
}

