const questionSchema = z.object({ label: z.string() });

// Terminal states never carry clickable questions — only a paused signal parks options for the
// user to pick from.
const signalSchema = z.object({
  state: z.enum(['done', 'failed', 'awaiting_input']),
  summary: z.string().min(1),
});

export function parseSignal(input: unknown) {
  return signalSchema.safeParse(input);
}

