// Paths that should cause the native-module verification job to run. Native module resolution is
// driven by installed dependency versions, so a change to how dependencies are declared belongs
// in this list.
export const WATCHED_PATHS = ['package.json', 'scripts/rebuild-native.mjs'] as const;

export function shouldRunNativeCheck(changedPaths: string[]): boolean {
  return changedPaths.some((p) => (WATCHED_PATHS as readonly string[]).includes(p));
}

