import { setTaskStatusIf, getTask } from '../store/tasks';

// Server-side retry: flip a failed/parked task back to running with a CAS so a stale attempt
// can't be resumed twice by two concurrent requests.
export async function retryTask(taskId: string): Promise<void> {
  const task = await getTask(taskId);
  if (!task || (task.status !== 'failed' && task.status !== 'parked')) return;
  await setTaskStatusIf(taskId, ['failed', 'parked'], 'running');
}

