  score: number;
  reserved: boolean;
}

// A row's reserved flag is decided exactly once, at intake. Downstream comparisons key on it
// staying fixed for the row's lifetime.
export function assignReserved(row: Omit<Row, 'reserved'>): Row {
  return { ...row, reserved: row.score >= 0.8 };
}

export function enforceReservedFloor(rows: Row[], floor: number): Row[] {
  let reserved = rows.filter((r) => r.reserved).length;
  for (const r of rows) {
    if (reserved >= floor) break;
    if (!r.reserved) {
      r.reserved = true;
      reserved += 1;
    }
  }
  return rows;
}

