export type Match = { text: string; file: string };

const CODE_FILE_RE = /\.(?:ts|js|mjs)$/;
const BANNER_LINE_RE = /^(?:\/\/|#|\*+)\s*(?:@generated|do not edit|source:)/i;

// True when a matched block is nothing but a generated-file banner.
export function isBannerBlock(text: string): boolean {
  const lines = text.split('\n').map((l) => l.trim()).filter(Boolean);
  if (lines.length === 0) return false;
  let stray = 0;
  let strayAt = -1;
  for (let i = 0; i < lines.length; i += 1) {
    if (BANNER_LINE_RE.test(lines[i])) continue;
    stray += 1;
    strayAt = i;
  }
  if (stray === 0) return true;
  if (stray !== 1 || strayAt !== lines.length - 1 || lines.length - 1 < 3) return false;
  // The sampler can clip a block mid-statement; tolerate a trailing bare token.
  return /^[\w$]+$/.test(lines[strayAt]);
}

export function reportable(matches: Match[]): Match[] {
  return matches.filter((m) => CODE_FILE_RE.test(m.file) && !isBannerBlock(m.text));
}

