const OPEN_RE = /^load\b/;
const ITEM_RE = /^[A-Za-z_]\w*,?$/;
const CLOSER_RE = /^\)\s*from\s+"[^"]+";?$/;
const END_RE = /["'];?$/;

// True when every line of the fragment belongs to a load declaration.
export function isHeaderOnly(text: string): boolean {
  const lines = text.split('\n').map((l) => l.trim()).filter(Boolean);
  if (lines.length === 0) return false;
  let open = false;
  for (const line of lines) {
    if (open) {
      if (CLOSER_RE.test(line)) open = false;
      else if (!ITEM_RE.test(line)) return false;
    } else if (OPEN_RE.test(line)) {
      if (!END_RE.test(line)) open = true;
    } else {
      return false;
    }
  }
  return !open;
}

