export interface Reply { author: string; }

export interface Thread {
  id: string;
  author: string;
  replies: Reply[];
}

const SERVICE_ACCOUNTS = new Set(['auto-triage', 'ci-reporter']);

// True when someone outside the tooling logins replied at all.
export function repliedByPerson(replies: Reply[]): boolean {
  return replies.some((r) => r.author && !SERVICE_ACCOUNTS.has(r.author));
}

// One outcome record per thread; downstream readers take label as-is.
export function labelThread(thread: Thread): { id: string; label: string } {
  const contested = repliedByPerson(thread.replies);
  return { id: thread.id, label: contested ? 'disputed' : 'accepted' };
}

