// Grammar: a directive is either single-line — load "x";  or  load "x" as y; —
// or a list: load ( opener, one "item" line each, closed by a lone ); line.
const OPEN_RE = /^load\b/;
const DONE_RE = /(?:"|"\s+as\s+[\w$]+);$/;
const LIST_CLOSE_RE = /^\);$/;

// Recipes pulling the same modules always share this block, so a repeated run of
// them is treated as unavoidable overlap and dropped from the report upstream.
export function isLoadHeader(fragment: string): boolean {
  const lines = fragment
    .split('\n')
    .map((l) => l.trim())
    .filter(Boolean);
  if (lines.length === 0) return false;
  let inList = false;
  for (const line of lines) {
    if (inList) {
      inList = !LIST_CLOSE_RE.test(line);
    } else if (!OPEN_RE.test(line)) {
      return false;
    } else if (!DONE_RE.test(line)) {
      inList = true;
    }
  }
  return true;
}

