type StoredResult = { id: string; status: string; result: unknown };
const results: Record<string, StoredResult> = Object.create(null);
export function seedJobs(rows: StoredResult[]) {
  for (const id of Object.keys(results)) delete results[id];
  for (const row of rows) results[row.id] = structuredClone(row);
}
export async function getJob(id: string) { return results[id] && structuredClone(results[id]); }
export async function updateJob(id: string, fields: Partial<StoredResult>) {
  if (results[id]) results[id] = { ...results[id], ...fields };
}

