    if (id === 'size') {
      reports.size = { summary: summarize(input.rows, { cascade: false }),
        banner: runBannerLines(input.plan, input.settings),
        timing: firstPassMeanLines(input.plan.map(p => ({ model: p.reviewer.model ?? input.settings.model, results: p.rows })), input.settings.table) };
    } else if (id === 'fanout') {
      const groups = [...groupByPair(input.rows).values()];
      reports.fanout = { families: groups.length, members: groups.map(group => group.map(row => row.id)), tally: classifyFlip(input.deltas) };
    } else if (id === 'dup') {
      const comments = extractCommentLines(input.files);
      reports.dup = { twins: nearTwins(input.rows), commentOverlap: comments.map(line => jaccard(wordsOf(line), wordsOf(input.settings.note ?? ''))) };
    } else if (id === 'structure') {
      const shared = input.rows.filter(row => input.previous[row.id]);
      const unchanged = shared.filter(row => rowUnchanged(input.previous[row.id], row));
      const stable = unchanged.filter(row => row.stable !== false && ['FAIL', 'PASS'].includes(row.expected));
      const hasRowHash = shared.every(row => { const previous = input.previous[row.id]; return (previous.behaviorHash !== undefined && row.behaviorHash !== undefined) || (previous.rowHash !== undefined && row.rowHash !== undefined); });
      reports.structure = {
        drift: shared.filter(row => !rowUnchanged(input.previous[row.id], row)).map(row => row.id),
        contrast: buildCompareReport({ pairs: stable.map(row => ({ id: row.id, caseId: row.caseId, expected: row.expected,
          wasOk: input.previous[row.id].okFirst, isOk: row.okFirst })), crossGate: false, shared: shared.length,
