type StatusRow = { id: string; status: string };
const states = new Map<string, string>();
export function seedJobs(rows: StatusRow[]) { states.clear(); rows.forEach(row => states.set(row.id, row.status)); }
export async function getJob(id: string) { const status = states.get(id); return status === undefined ? undefined : { id, status }; }
export async function updateJobStatus(id: string, status: string) { if (states.has(id)) states.set(id, status); }
export async function updateJobStatusIf(id: string, allowed: string[], next: string) {
  const current = states.get(id);
  if (current === undefined || !allowed.includes(current)) return 0;
  states.set(id, next);
  return 1;
}

