export interface Job { id: string; status: string; startMode: string; result: unknown; }
const jobs = new Map<string, Job>();
export function seedJobs(rows: Job[]) { jobs.clear(); for (const job of rows) jobs.set(job.id, structuredClone(job)); }
export async function getJob(id: string) { const job = jobs.get(id); return job && structuredClone(job); }
export async function updateJob(id: string, patch: Partial<Job>) { const job = jobs.get(id); if (job) Object.assign(job, patch); }
export async function listJobsByStatus(status: string) { return [...jobs.values()].filter(job => job.status === status).map(job => structuredClone(job)); }

